<section class="user-area"><div class="container user-layout"><?php require view_path('components/user/sidebar.php'); ?><div class="user-main"><header class="user-page-head"><div><span class="eyebrow">Updates</span><h1>اعلان‌ها</h1><p>تغییرات دوره‌ها، رویدادها و پیام‌های مهم حساب.</p></div><?php if ($unread): ?><form method="post" action="/notifications/read-all"><?= csrf_field() ?><button class="btn btn--ghost btn--sm" type="submit">علامت‌گذاری همه به‌عنوان خوانده‌شده</button></form><?php endif; ?></header><div class="notification-list"><?php foreach ($user['notifications'] ?? [] as $notification): ?><article class="notification-item <?= empty($notification['read_at']) ? 'is-unread' : '' ?>"><span>◉</span><div><h2><?= e($notification['title']) ?></h2><p><?= e($notification['message']) ?></p><small><?= e(substr($notification['created_at'], 0, 10)) ?></small></div><?php if (empty($notification['read_at'])): ?><em>جدید</em><?php endif; ?></article><?php endforeach; ?><?php if (empty($user['notifications'])): ?><div class="user-empty"><span>◉</span><h2>اعلان جدیدی ندارید</h2><p>پیام‌های مهم Mentoris در این بخش نمایش داده می‌شوند.</p></div><?php endif; ?></div></div></div></section>
